/**
 * `bun run css` — emits the tokens as CSS custom properties.
 *
 * The TypeScript tokens are the source of truth; this is a rendering of them.
 * Phase 14 consumes the output, so the palette the interface uses is the same
 * one the contrast tests verify — not a hand-copy that drifts.
 */
import { MOTION, RADIUS, SPACE, STATUS, THEME, TYPE } from '../tokens.ts';

const lines: string[] = [
  '/* Generated by @nexus/design-tokens. Do not edit by hand. */',
  '/* Source of truth: packages/design-tokens/src/tokens.ts */',
  '',
  ':root {',
];

for (const [key, value] of Object.entries(THEME.light)) {
  lines.push(`  --nx-${kebab(key)}: ${value};`);
}
for (const [key, value] of Object.entries(STATUS)) {
  lines.push(`  --nx-status-${key}: ${value.light};`);
}
for (const [key, value] of Object.entries(SPACE)) lines.push(`  --nx-space-${key}: ${value};`);
for (const [key, value] of Object.entries(TYPE.scale)) lines.push(`  --nx-text-${key}: ${value}rem;`);
for (const [key, value] of Object.entries(MOTION.duration)) lines.push(`  --nx-dur-${key}: ${value};`);
for (const [key, value] of Object.entries(MOTION.easing)) lines.push(`  --nx-ease-${key}: ${value};`);
for (const [key, value] of Object.entries(RADIUS)) lines.push(`  --nx-radius-${key}: ${value};`);
lines.push(`  --nx-font-mono: ${TYPE.family.mono};`);
lines.push(`  --nx-font-sans: ${TYPE.family.sans};`);
lines.push('}', '');

const darkBlock = [
  ...Object.entries(THEME.dark).map(([k, v]) => `    --nx-${kebab(k)}: ${v};`),
  ...Object.entries(STATUS).map(([k, v]) => `    --nx-status-${k}: ${v.dark};`),
];

// Three states, not two: an explicit choice stamps data-theme, and the default
// "system" setting stamps nothing at all.
lines.push('@media (prefers-color-scheme: dark) {', '  :root:not([data-theme="light"]) {');
lines.push(...darkBlock);
lines.push('  }', '}', '');
lines.push(':root[data-theme="dark"] {');
lines.push(...darkBlock.map((l) => l.slice(2)));
lines.push('}', '');
lines.push('@media (prefers-reduced-motion: reduce) {');
lines.push('  :root {');
for (const key of Object.keys(MOTION.duration)) {
  lines.push(`    --nx-dur-${key}: ${MOTION.reducedMotionFallback};`);
}
lines.push('  }', '}');

function kebab(text: string): string {
  return text.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`);
}

console.log(lines.join('\n'));
